#!/usr/bin/env node

// Gate: brand identity. Config-driven port of the monorepo's brand-literal
// ratchet — shipped by create-sailor into scaffolded projects. It hardcodes NO
// paths: governed directories, detected literal patterns, permanent exemptions,
// and the shrink-only allowlist all come from governance.config.json
// (brandLiterals section), with sensible scaffold-layout defaults.
//
// CI guard: brand identity literals — applied to governed app code and commerce
// + email packages. The brand source of truth is @nebutra/brand/metadata
// (generated by `pnpm brand:apply`). Raw hardcoded strings like "Nebutra",
// "云毓智能", "nebutra.com", "#0033FE" in app code are governance violations.
//
// SHRINK-ONLY ratchet:
//   • A NEW file containing a raw brand literal => FAIL.
//   • A listed file that no longer contains raw brand literals (migrated) => FAIL
//     — remove it from the allowlist.
//   • Existing offenders migrate ON-TOUCH; the allowlist may only shrink.
//
// Escape hatch: top-level `// @brand-exempt: <reason>` in any file skips
// enforcement — for files that legitimately cannot use CSS vars or brand imports
// (e.g. global-error.tsx, which renders outside the root layout).
//
// Permanent exemptions (stories, tests, previews, the brand/tokens packages
// themselves) live in knownExemptPatterns, not the allowlist.
//
// A fresh scaffold has ZERO brand debt → the allowlist default is EMPTY.
//
// Run: node scripts/governance/lint-brand-literals.mjs

import { execSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { loadGovernanceConfig } from "./_config.mjs";

// Same resolution `loadGovernanceConfig` uses, so --prune rewrites the file the
// engine actually read.
const CONFIG_PATH = resolve(process.cwd(), "governance.config.json");

const cfg = loadGovernanceConfig("brandLiterals");

const governedPaths = cfg.governedPaths;
const allowExpressions = cfg.allowExpressions;
const knownExemptPatterns = cfg.knownExemptPatterns.map((p) => new RegExp(p));
const allowlist = new Set(cfg.allowlist);

// Build a single alternation pattern for grep from the allow expressions.
// Each expression may already be a regex fragment (e.g. "nebutra\\.com").
const grepPattern = allowExpressions.join("|");

const isExempt = (p) => knownExemptPatterns.some((re) => re.test(p));

// Run grep across all governed paths. LANG=en_US.UTF-8 for CI UTF-8 safety
// (Chinese chars 云毓智能 must match correctly). --include limits to .ts/.tsx.
const grepRoots = governedPaths.join(" ");
const grepCommand =
  `LANG=en_US.UTF-8 grep -rlE '${grepPattern}' --include='*.ts' --include='*.tsx' ${grepRoots} 2>/dev/null` +
  " | grep -v node_modules | grep -v '/dist/' | grep -v '/.next/' | grep -v '/generated/'";

let raw = "";
try {
  raw = execSync(grepCommand, { encoding: "utf-8" }).trim();
} catch {
  raw = "";
}

const candidates = raw
  .split("\n")
  .map((p) => p.replace(/^\.\//, ""))
  .filter(Boolean)
  .filter((p) => !isExempt(p));

const detected = new Set();
for (const file of candidates) {
  let src = "";
  try {
    src = readFileSync(file, "utf-8");
  } catch {
    continue;
  }
  // Honor the file-level escape hatch.
  if (/\/\/\s*@brand-exempt/.test(src)) continue;
  detected.add(file);
}

const newViolations = [...detected].filter((f) => !allowlist.has(f)).sort();
const fixedButListed = [...allowlist].filter((f) => existsSync(f) && !detected.has(f)).sort();
// Entries whose file is gone. These were invisible before: every other check
// skipped them via existsSync, so a deleted file's allowance lived forever and
// silently pre-approved anything recreated at the same path.
const deletedButListed = [...allowlist].filter((f) => !existsSync(f)).sort();

const stale = [...new Set([...fixedButListed, ...deletedButListed])].sort();

// `--prune` rewrites the allowlist instead of asking a human to hand-edit it.
// The list is shrink-only, so removing entries is always safe; making the
// remedy one command is what stops "❌ you fixed something" from being a
// hostile failure.
if (process.argv.includes("--prune")) {
  if (stale.length === 0) {
    process.stdout.write("✓ brand-literals allowlist already minimal\n");
    process.exit(0);
  }
  const raw = JSON.parse(readFileSync(CONFIG_PATH, "utf8"));
  const before = raw.brandLiterals.allowlist.length;
  raw.brandLiterals.allowlist = raw.brandLiterals.allowlist
    .filter((f) => !stale.includes(f))
    .sort();
  writeFileSync(CONFIG_PATH, `${JSON.stringify(raw, null, 2)}\n`);
  process.stdout.write(
    `✓ pruned ${stale.length} entr${stale.length === 1 ? "y" : "ies"} ` +
      `(${before} → ${raw.brandLiterals.allowlist.length})\n` +
      stale.map((f) => `   - ${f}`).join("\n") +
      "\n",
  );
  process.exit(0);
}

let failed = false;

if (newViolations.length > 0) {
  failed = true;
  process.stderr.write(
    "\n❌ Brand-literal violation — these files contain raw brand literals\n" +
      "   (Nebutra, 云毓智能, 云毓, nebutra.<tld>, #0033FE, #0BF1C3).\n" +
      "   Route brand identity through @nebutra/brand/metadata (brand.name,\n" +
      "   brand.domains.*) or token vars (var(--brand-primary),\n" +
      "   var(--brand-accent)) — never hardcode.\n" +
      "   Or add `// @brand-exempt: <reason>` if the file truly cannot use vars:\n" +
      newViolations.map((f) => `   - ${f}`).join("\n") +
      "\n",
  );
}

if (stale.length > 0) {
  failed = true;
  const migrated = fixedButListed.length
    ? "   migrated (no longer contain brand literals):\n" +
      fixedButListed.map((f) => `   - ${f}`).join("\n") +
      "\n"
    : "";
  const deleted = deletedButListed.length
    ? "   deleted (file no longer exists):\n" +
      deletedButListed.map((f) => `   - ${f}`).join("\n") +
      "\n"
    : "";
  process.stderr.write(
    "\n❌ The brand-literal allowlist has stale entries. It is shrink-only, so\n" +
      "   these must go. Run:  node scripts/lint-brand-literals.mjs --prune\n" +
      migrated +
      deleted,
  );
}

if (failed) process.exit(1);

process.stdout.write(
  `✓ brand-literals: ${allowlist.size} known allowlisted file(s), 0 new. ` +
    "Migrate allowlisted files on-touch to shrink the list toward zero.\n",
);
